  var MEDIS = [['jantung', 'Penyakit jantung'], ['diabetes', 'Diabetes'], ['hepatitis', 'Hepatitis'], ['lain', 'Penyakit lainnya'], ['alergiObat', 'Alergi obat'], ['alergiMakanan', 'Alergi makanan']];
  var sModal = null, sOrigin = '', sEditing = false, sVal = {};
