    sVal = { gender: p.gender === 'p' ? 'p' : 'l', pay: 'cash', gol: md.gol || '', tensiK: md.tensiK || '' };
    MEDIS.forEach(function (m) { var x = md[m[0]] || {}; sVal['m_' + m[0]] = x.s || (x.k ? 'Ada' : ''); sEl('mt_' + m[0]).value = x.k || ''; });
