    var v = item.draft && item.draft.visit;
    if (v) { sEl('vtgl').value = ddmmyyToHtmlDate(v.tanggal); sEl('vgigi').value = v.gigi || ''; sEl('vrawat').value = v.perawatan || ''; sEl('vbiaya').value = v.biaya || ''; sVal.pay = v.metode === 'qr' ? 'qr' : 'cash'; sEl('vparaf').value = v.paraf || ''; paintPills(); sModal.querySelector('details').open = true; }
    var jg = window.KilawDokter && window.KilawDokter.jaga(); sEl('vparaf').placeholder = jg ? jg.inisial : 'Owner';
    sModal.hidden = false; sModal.style.display = 'flex'; sModal.scrollTop = 0;
